:root {
    --hims-primary:       #16a34a;
    --hims-primary-dark:  #15803d;
    --hims-primary-light: #22c55e;
    --hims-primary-xlight:#dcfce7;
    --hims-primary-pale:  #f0fdf4;
    --hims-white:         #ffffff;
    --hims-surface:       #f8fffe;
    --hims-border:        #bbf7d0;
    --hims-text:          #14532d;
    --hims-text-muted:    #4ade80;
    --hims-text-dark:     #052e16;
    --hims-gray:          #6b7280;
    --hims-gray-light:    #f3f4f6;
    --hims-danger:        #dc2626;
    --hims-warning:       #d97706;
    --hims-info:          #0891b2;
    --hims-sidebar-w:     260px;
    --hims-topbar-h:      64px;
    --hims-ai-w:          340px;
    --hims-ai-offset:     0px;
    --hims-radius:        12px;
    --hims-radius-sm:     8px;
    --hims-shadow:        0 1px 3px rgba(22,163,74,.08), 0 4px 16px rgba(22,163,74,.06);
    --hims-shadow-md:     0 4px 24px rgba(22,163,74,.12), 0 1px 4px rgba(0,0,0,.04);
    --hims-shadow-lg:     0 8px 40px rgba(22,163,74,.18), 0 2px 8px rgba(0,0,0,.06);
    --hims-transition:    all .18s cubic-bezier(.4,0,.2,1);
}

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

*, *::before, *::after { box-sizing: border-box; }

body {
    font-family: 'Inter', system-ui, sans-serif;
    background: var(--hims-surface);
    color: var(--hims-text-dark);
    margin: 0;
    min-height: 100vh;
}

.hims-sidebar {
    position: fixed;
    top: 0; left: 0;
    width: var(--hims-sidebar-w);
    height: 100vh;
    background: linear-gradient(180deg, #052e16 0%, #14532d 40%, #15803d 100%);
    display: flex;
    flex-direction: column;
    z-index: 100;
    overflow-y: auto;
    transition: var(--hims-transition);
}

.hims-sidebar::-webkit-scrollbar { width: 4px; }
.hims-sidebar::-webkit-scrollbar-track { background: transparent; }
.hims-sidebar::-webkit-scrollbar-thumb { background: rgba(255,255,255,.2); border-radius: 4px; }

.hims-topbar {
    position: fixed;
    top: 0;
    left: var(--hims-sidebar-w);
    right: var(--hims-ai-offset);
    height: var(--hims-topbar-h);
    background: var(--hims-white);
    border-bottom: 1px solid var(--hims-border);
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 28px;
    z-index: 99;
    box-shadow: 0 1px 0 var(--hims-border);
    transition: right .18s cubic-bezier(.4,0,.2,1);
}

.topbar-left { display: flex; align-items: center; gap: 12px; }
.hims-menu-toggle {
    display: none;
    width: 40px; height: 40px;
    ...
}
.hims-sidebar-backdrop {
    display: none;
    position: fixed;
    inset: 0;
    background: rgba(5,46,22,.5);
    z-index: 99;
    opacity: 0;
    transition: opacity .3s ease;
}
.hims-sidebar-backdrop.open { opacity: 1; }
.topbar-right { display: flex; align-items: center; gap: 12px; }

.hims-main {
    margin-left: var(--hims-sidebar-w);
    margin-top: var(--hims-topbar-h);
    margin-right: var(--hims-ai-offset);
    padding: 28px;
    min-height: calc(100vh - var(--hims-topbar-h));
    transition: margin-right .18s cubic-bezier(.4,0,.2,1);
}
body.ai-resizing .hims-main,
body.ai-resizing .hims-topbar,
body.ai-resizing #ai-rail { transition: none; }
body.ai-resizing { cursor: col-resize; user-select: none; }

.topbar-dropdown {
    position: absolute;
    top: calc(100% + 10px);
    right: 0;
    width: 320px;
    max-width: calc(100vw - 32px);
    ...
    z-index: 1100;
    opacity: 0;
    transform: translateY(-6px) scale(.98);
    pointer-events: none;
    transition: opacity .16s ease, transform .16s ease;
