}

.notif-dropdown { width: 390px; border-color: #e5e7eb; border-radius: 16px; }
.notif-heading { ... color: #111827; }
.notif-list { max-height: min(560px, calc(100vh - 110px)); ... }
.notif-item:hover { background: #f3f4f6; }
