.global-search-box:focus-within { border-color: #1877f2; background: #fff; box-shadow: 0 0 0 3px rgba(24,119,242,.12); }
.global-search-results { max-height: min(590px, calc(100vh - 120px)); overflow-y: auto; padding: 0 8px 10px; }
