@keyframes searchSpin { to { transform: rotate(360deg); } }

#ai-rail {
    position: fixed;
    top: 0;
    right: 0;
    bottom: 0;
    width: var(--hims-ai-w);
    max-width: 100vw;
    background: var(--hims-white);
    border-left: 1px solid var(--hims-border);
    display: flex;
    flex-direction: column;
    z-index: 98;
    transform: translateX(100%);
    visibility: hidden;
    transition: transform .18s cubic-bezier(.4,0,.2,1), visibility 0s .18s;
}
#ai-rail.open {
    transform: translateX(0);
    visibility: visible;
    transition: transform .18s cubic-bezier(.4,0,.2,1), visibility 0s 0s;
    box-shadow: -8px 0 32px rgba(5,46,22,.06);
}

#ai-rail-resizer {
    position: absolute;
    top: 0; bottom: 0; left: -3px;
    width: 7px;
    cursor: col-resize;
    background: transparent;
    z-index: 2;
}
#ai-rail-resizer:hover,
#ai-rail-resizer:focus-visible { background: var(--hims-primary-light); outline: none; }
#ai-rail-header {
    display: flex;
    align-items: center;
    gap: 4px;
    height: var(--hims-topbar-h);
    flex-shrink: 0;
    padding: 0 8px 0 16px;
    border-bottom: 1px solid var(--hims-border);
    background: var(--hims-primary-pale);
}
#ai-rail-title { flex: 1; min-width: 0; font-size: 13px; font-weight: 700; ... white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ai-rail-icon { width: 30px; height: 30px; ... border-radius: 8px; transition: var(--hims-transition); }
.ai-rail-icon:hover  { background: var(--hims-primary-xlight); }
.ai-rail-icon.active { background: var(--hims-primary); color: #fff; }

#ai-sessions {
    flex-shrink: 0;
    max-height: 40%;
    overflow-y: auto;
    border-bottom: 1px solid var(--hims-border);
    background: #fbfefc;
}
#ai-sessions[hidden] { display: none; }
.ai-sessions-clear:hover { background: #fee2e2; }
.ai-session { display: flex; align-items: center; gap: 2px; padding: 2px 8px 2px 14px; }
.ai-session:hover        { background: var(--hims-primary-pale); }
.ai-session.active       { background: var(--hims-primary-xlight); }
.ai-session-act { width: 24px; height: 24px; ... opacity: 0; transition: opacity .12s, background .12s, color .12s; }
.ai-session:hover .ai-session-act,
.ai-session-act:focus-visible { opacity: 1; }

#ai-messages {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 16px;
    background: #f8fdf9;
}
.ai-msg {
    padding: 10px 14px;
    border-radius: 10px;
    font-size: 13.5px;
    line-height: 1.55;
    max-width: 92%;
    overflow-wrap: anywhere;
    white-space: pre-wrap;
}
.ai-msg.user { align-self: flex-end; background: var(--hims-primary-xlight); color: var(--hims-text); border: 1px solid var(--hims-border); }
.ai-msg.ai { align-self: flex-start; background: var(--hims-white); color: #374151; border: 1px solid #e5e7eb; }
.ai-msg.thinking { align-self: flex-start; background: var(--hims-white); color: var(--hims-gray); font-style: italic; border: 1px solid #e5e7eb; }
.ai-msg.ai.did-ok      { background: var(--hims-primary-xlight); color: var(--hims-primary-dark); border-color: var(--hims-primary); }
.ai-msg.ai.did-error   { background: #fee2e2; color: #991b1b; border-color: var(--hims-danger); }
.ai-msg.ai.did-pending { background: #fef3c7; color: #92400e; border-color: var(--hims-warning); }

#ai-input-row {
    display: flex;
    gap: 8px;
    flex-shrink: 0;
    padding: 12px 14px;
    background: var(--hims-white);
    border-top: 1px solid var(--hims-border);
}
#ai-input {
    flex: 1;
    min-width: 0;
    border: 1px solid #d1d5db;
    border-radius: 8px;
    padding: 8px 12px;
    font-family: inherit;
    font-size: 13.5px;
    line-height: 1.45;
    resize: none;
    max-height: 120px;
    transition: border-color .15s;
}
#ai-input:focus { outline: none; border-color: var(--hims-primary); }
#ai-send-btn { width: 36px; height: 36px; flex-shrink: 0; align-self: flex-end; ... background: var(--hims-primary); color: #fff; transition: background .15s; }
#ai-send-btn:hover    { background: var(--hims-primary-dark); }
#ai-send-btn:disabled { background: #9ca3af; cursor: not-allowed; }
.topbar-btn#ai-toggle.active { background: var(--hims-primary); color: #fff; }

